-- Initial editorial pool. Level bands and weights are application presets, not DMG tables.
-- Existing personal items opt in explicitly; artifacts and vehicles are not random defaults.
UPDATE dndshare.item SET data=data || jsonb_build_object('treasure',jsonb_build_object(
 'weight',CASE WHEN type_id=19 OR type_id=10 THEN CASE COALESCE(data->>'rarity','0') WHEN '0' THEN 20 WHEN '1' THEN 10 WHEN '2' THEN 4 WHEN '3' THEN 2 ELSE 1 END ELSE 10 END,
 'min_level',CASE WHEN type_id=19 OR type_id=10 THEN CASE COALESCE(data->>'rarity','0') WHEN '2' THEN 5 WHEN '3' THEN 11 WHEN '4' THEN 17 ELSE 1 END ELSE 1 END,'max_level',20))
WHERE user_id IS NULL AND ((type_id IN (19,10) AND COALESCE(data->>'rarity','0') IN ('0','1','2','3','4'))
 OR (type_id IN (1,2,12,14) AND data->>'available_in_starting_shop'='true'));
